 import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, color as nodeColor } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const palette =
    config.visual?.colors ??
    config.intent?.visualSpec?.colors ??
    { ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10' };

  const group = new THREE.Group();
  group.name = 'stat-tile';

  const w = 2.2;
  const h = 1.4;
  const corner = 0.15;

  const shape = new THREE.Shape();
  shape.moveTo(-w / 2 + corner, -h / 2);
  shape.lineTo(w / 2 - corner, -h / 2);
  shape.quadraticCurveTo(w / 2, -h / 2, w / 2, -h / 2 + corner);
  shape.lineTo(w / 2, h / 2 - corner);
  shape.quadraticCurveTo(w / 2, h / 2, w / 2 - corner, h / 2);
  shape.lineTo(-w / 2 + corner, h / 2);
  shape.quadraticCurveTo(-w / 2, h / 2, -w / 2, h / 2 - corner);
  shape.lineTo(-w / 2, -h / 2 + corner);
  shape.quadraticCurveTo(-w / 2, -h / 2, -w / 2 + corner, -h / 2);

  const cardGeo = new THREE.ExtrudeGeometry(shape, {
    depth: 0.12,
    bevelEnabled: true,
    bevelThickness: 0.03,
    bevelSize: 0.03,
    bevelSegments: 4
  });
  cardGeo.center();

  const cardMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(palette.surface),
    metalness: 0.5,
    roughness: 0.62,
    clearcoat: 0.18,
    clearcoatRoughness: 0.45,
    ior: 1.45
  });

  const card = new THREE.Mesh(cardGeo, cardMat);
  card.castShadow = true;
  card.receiveShadow = true;
  group.add(card);

  const panelGeo = new THREE.PlaneGeometry(w * 0.92, h * 0.88);
  const panelMat = new MeshBasicNodeMaterial({});
  panelMat.colorNode = mix(
    nodeColor(palette.surface),
    nodeColor(palette.ink),
    smoothstep(uv().y, 0.1, 0.9)
  );
  const panel = new THREE.Mesh(panelGeo, panelMat);
  panel.position.z = 0.07;
  card.add(panel);

  const accentMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(palette.accent),
    emissive: new THREE.Color(palette.accent),
    emissiveIntensity: 0.9,
    metalness: 0.4,
    roughness: 0.45
  });
  const edgeGeo = new THREE.TorusGeometry(Math.min(w, h) / 2 - 0.06, 0.015, 8, 64);
  const accentEdge = new THREE.Mesh(edgeGeo, accentMat);
  accentEdge.position.z = 0.08;
  card.add(accentEdge);

  const shadowGeo = new THREE.CircleGeometry(1.35, 32);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new THREE.Color(0x000000),
    transparent: true,
    opacity: 0.45
  });
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -h / 2 - 0.25;
  group.add(shadow);

  const keyLight = new THREE.DirectionalLight(new THREE.Color(palette.paper), 1.1);
  keyLight.position.set(2.2, 3.0, 2.5);
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight(new THREE.Color(palette.accent), 0.7);
  rimLight.position.set(-2.0, 0.8, -2.0);
  group.add(rimLight);

  const fillLight = new THREE.PointLight(new THREE.Color(palette.paper), 0.5);
  fillLight.position.set(0, 1.8, 1.8);
  group.add(fillLight);

  const tweens = [];
  const primResources = [];

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const model = gltf.scene;
      model.scale.setScalar(0.32);
      model.position.set(0.55, 0, 0.18);
      model.traverse((obj) => {
        if (obj.isMesh) {
          obj.castShadow = true;
          obj.receiveShadow = true;
          if (obj.material) {
            obj.material.roughness = Math.max(obj.material.roughness ?? 0.5, 0.5);
            obj.material.metalness = Math.min(obj.material.metalness ?? 0, 0.55);
          }
        }
      });
      card.add(model);

      const spin = gsap.to(model.rotation, {
        z: Math.PI * 2,
        duration: 18,
        repeat: -1,
        ease: 'none'
      });
      tweens.push(spin);
    });
  }

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item.text) continue;
    const txt = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? 0.13,
      color: item.role === 'label' ? palette.paper : palette.accent,
      align: 'left'
    });
    txt.position.set(-w * 0.35, item.role === 'label' ? -0.2 : 0.15, 0.09);
    card.add(txt);
  }

  const baseY = group.position.y;

  function setHover(active) {
    const t = gsap.to(group.position, {
      y: active ? baseY + 0.15 : baseY,
      duration: active ? 0.35 : 0.4,
      ease: 'power2.out',
      overwrite: true
    });
    tweens.push(t);

    const g = gsap.to(accentMat, {
      emissiveIntensity: active ? 1.6 : 0.9,
      duration: 0.3,
      overwrite: true
    });
    tweens.push(g);
  }

  function press(active) {
    const s = gsap.to(group.scale, {
      x: active ? 0.97 : 1,
      y: active ? 0.97 : 1,
      z: active ? 0.97 : 1,
      duration: active ? 0.12 : 0.25,
      ease: active ? 'back.out(2)' : 'power2.out',
      overwrite: true
    });
    tweens.push(s);
  }

  group.userData.handlers = {
    hover: (active) => setHover(active),
    click: () => ctx.emit('hub-home.select'),
    onPointerEnter: () => setHover(true),
    onPointerLeave: () => setHover(false),
    onPointerDown: () => press(true),
    onPointerUp: () => press(false)
  };

  group.scale.set(0.95, 0.95, 0.95);
  const enter = gsap.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.75,
    ease: 'power3.out',
    delay: 0.05
  });
  tweens.push(enter);

  if (config.cinematicPrimitives) {
    for (const cp of config.cinematicPrimitives) {
      if (ctx.primitives[cp.name]) {
        const res = ctx.primitives[cp.name](group, cp.params);
        if (res) primResources.push(res);
      }
    }
  }

  group.userData.cleanup = () => {
    tweens.forEach((t) => t && t.kill && t.kill());
    primResources.forEach((r) => r && r.cleanup && r.cleanup());
    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return group;
}
